style.css:
body {
  background-image: url("https://cdn.cosmos.so/9228f3e9-26b4-448b-9bc1-6e323a818352?format=jpeg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  height: 100vh;
  margin: 0;

  /* Filtros artísticos */
  filter: contrast(110%) saturate(120%) brightness(95%);

  /* Centrado de contenido */
  display: flex;
  justify-content: center;
  align-items: center;
}
